class Uploader:
    def __init__(self):
        self.queue = []

    def flush(self):
        self.send(self.queue)
        self.queue = []

class Trainer:
    def step(self):
        self.n += 1

    def maybe_save(self, path):
        self.save(path)
        self.saved += 1

class Session:
    def open(self):
        self.alive = True

    def close(self):
        self.conn.close()
        self.alive = False

class Grid:
    def __init__(self, w, h):
        self.w, self.h = w, h

    def contains(self, x, y):
        return 0 <= x < self.w and 0 <= y < self.h

class Cart:
    def add(self, item):
        self.items.append(item)

    def checkout(self):
        total = self.total()
        return self.pay(total)

class Monitor:
    def start(self):
        self.running = True

    def poll(self, ctx):
        self.tick(ctx)
        self.count += 1

class Tree:
    def __init__(self):
        self.root = None

    def find(self, key):
        return self._find(self.root, key)
